      "id": "fuzzy/apply_src.go:1:68",
      "file": "fuzzy/apply_src.go",
      "start_line": 1,
      "end_line": 68,
      "kind": "code_observation",
      "text": "// Copyright (c) HashiCorp, Inc.\n// SPDX-License-Identifier: MPL-2.0\n\npackage fuzzy\n\nimport (\n\t\"hash/fnv\"\n\t\"math/rand\"\n\t\"testing\"\n\t\"time\"\n)\n\ntype applySource struct {\n\trnd  *rand.Rand\n\tseed int64\n}\n\n// newApplySource will create a new source, any source created with the same seed will generate the same sequence of data.\nfunc newApplySource(seed string) *applySource {\n\th := fnv.New32()\n\th.Write([]byte(seed))\n\ts := &applySource{seed: int64(h.Sum32())}\n\ts.reset()\n\treturn s\n}\n\n// reset this source back to its initial state, it'll generate the same sequence of data it initially did\nfunc (a *applySource) reset() {\n\ta.rnd = rand.New(rand.NewSource(a.seed))\n}\n\nfunc (a *applySource) nextEntry() []byte {\n\tconst sz = 33\n\tr := make([]byte, sz)\n\tfor i := 0; i < len(r); i++ {\n\t\tr[i] = byte(a.rnd.Int31n(256))\n\t}\n\treturn r\n}\n\ntype clusterApplier struct {\n\tstopCh  chan bool\n\tapplied uint64\n\tsrc     *applySource\n}\n\n// runs apply in chunks of n to the cluster, use the returned Applier to Stop() it\nfunc (a *applySource) apply(t *testing.T, c *cluster, n uint) *clusterApplier {\n\tap := &clusterApplier{stopCh: make(chan bool), src: a}\n\tgo ap.apply(t, c, n)\n\treturn ap\n}\n\nfunc (ca *clusterApplier) apply(t *testing.T, c *cluster, n uint) {\n\tfor true {\n\t\tselect {\n\t\tcase <-ca.stopCh:\n\t\t\treturn\n\t\tdefault:\n\t\t\tca.applied += c.ApplyN(t, 5*time.Second, ca.src, n)\n\t\t}\n\t}\n}\n\nfunc (ca *clusterApplier) stop() {\n\tca.stopCh <- true\n\tclose(ca.stopCh)\n}",
      "content_digest": "ff31be638052375ce5daf8181f27de1d8bbb252a3e0167577a7147ce4e73b9b5"
    },
