      "kind": "code_observation",
      "text": "name: ci\n\non:\n  pull_request:\n    branches: [\"main\"]\n  push:\n    branches: [\"main\"]\n    tags: [\"*\"]\n\npermissions:\n  contents: read\n\njobs:\n  go-fmt-and-vet:\n    runs-on: ubuntu-22.04\n    steps:\n    - uses: actions/checkout@ac593985615ec2ede58e132d2e21d2b1cbd6127c # v3.3.0\n    - uses: actions/setup-go@6edd4406fa81c3da01a34fa6f6343087c207a568 # v3.5.0\n      with:\n        go-version: '1.20'\n        cache: true\n    - run: |\n        files=$(go fmt ./...)\n        if [ -n \"$files\" ]; then\n          echo \"The following file(s) do not conform to go fmt:\"\n          echo \"$files\"\n          exit 1\n        fi\n    - run: |\n        PACKAGE_NAMES=$(go list ./... | grep -v github.com/hashicorp/raft/fuzzy)\n        go vet $PACKAGE_NAMES\n\n  go-test:\n    needs: go-fmt-and-vet\n    strategy:\n      matrix:\n        go: ['1.19', '1.20']\n        arch: ['x32', 'x64']\n    runs-on: ubuntu-22.04\n    env:\n      INTEG_TESTS: yes\n    steps:\n    - uses: actions/checkout@ac593985615ec2ede58e132d2e21d2b1cbd6127c # v3.3.0\n    - uses: actions/setup-go@6edd4406fa81c3da01a34fa6f6343087c207a568 # v3.5.0\n      with:\n        go-version: ${{ matrix.go }}\n        architecture: ${{ matrix.arch }}\n        cache: true\n    # x86 specific build.\n    - if: matrix.arch == 'x32'\n      run: |\n        sudo apt-get update\n        sudo apt-get install gcc-multilib\n        go test --tags batchtest ./...\n    # x86-64 specific build.\n    - if: matrix.arch == 'x64'\n      run: go test -race --tags batchtest ./...\n  go-test-compat:\n    needs: go-test\n    strategy:\n      matrix:\n        go: [ '1.20', '1.21', '1.22' ]\n        arch: [ 'x32', 'x64' ]\n    runs-on: ubuntu-22.04\n    steps:\n      - uses: actions/checkout@ac593985615ec2ede58e132d2e21d2b1cbd6127c # v3.3.0\n      - uses: actions/setup-go@6edd4406fa81c3da01a34fa6f6343087c207a568 # v3.5.0\n        with:\n          go-version: ${{ matrix.go }}\n          architecture: ${{ matrix.arch }}\n          cache: true\n          submodules: true\n      # x86 specific build.\n      - if: matrix.arch == 'x32'\n        run: |\n          sudo apt-get update\n          sudo apt-get install gcc-multilib\n          git submodule update --init --recursive\n          cd raft-compat\n          go mod tidy\n          go test ./...\n      # x86-64 specific build.\n      - if: matrix.arch == 'x64'\n        run: |\n          git submodule update --init --recursive\n          cd raft-compat\n          go mod tidy\n          go test -race ./...",
